5|     int* data;
6|     int size;
7|     int cap;
8| };
9| 
10| void init(DynArr& d) {
11|     d.cap = 4;
12|     d.size = 0;
13|     d.data = new int[d.cap];
14| }
15| 
16| void push(DynArr& d, int x) {
17|     if (d.size == d.cap) {
18|         int* bigger = new int[d.cap * 2];
19|         for (int i = 0; i < d.size; i++) bigger[i] = d.data[i];
20|         delete[] d.data;
21|         d.data = bigger;
22|         d.cap *= 2;
23|     }
24|     d.data[d.size++] = x;
25| }
26| 
27| int main() {
28|     DynArr d;
29|     init(d);
30|     int x;
31|     while (cin >> x) push(d, x);
32|     cout << d.size << "\n";
33|     for (int i = d.size - 1; i >= 0; i--) cout << d.data[i] << " ";
34|     cout << "\n";
35|     delete[] d.data;
36|     return 0;
37| }

