9| void mergeSort(int a[], int n) {
10|     for (int i = 1; i < n; i++) {
11|         int key = a[i];
12|         int j = i - 1;
13|         while (j >= 0 && a[j] > key) {
14|             a[j + 1] = a[j];
15|             j--;
16|         }
17|         a[j + 1] = key;
18|     }
19| }
